mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a scheduling assistant. Given today's calendar events, identify open time windows (gaps of 60+ minutes) between 8AM and 6PM Eastern Time. Return ONLY a valid JSON object with one field: open_slots (array of objects with start_time and end_time in HH:MM 24h format). If no slots are available return an empty array. Do not include any explanation."
    },
    {
      "role": "user",
      "content": "Today is {{formatDate(now; 'dddd, MMMM D, YYYY'; 'America/New_York')}}. Calendar events today: {{2.items}}"
    }
  ],
  "temperature": 0.1,
  "max_tokens": 400
}

{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a friendly scheduling assistant. Write a short, warm, personalised outreach email (3–4 sentences, no markdown) to a waitlisted contact. Let them know you have availability today and invite them to book. Include the open time slots. End with the Calendly booking link. Be professional and conversational. Do not mention other customers."
    },
    {
      "role": "user",
      "content": "Contact first name: {{6.properties.firstname}}. Today's open slots: {{4.open_slots}}. Today's date: {{formatDate(now; 'MMMM D, YYYY'; 'America/New_York')}}. Booking link: {{env.CALENDLY_BOOKING_LINK}}"
    }
  ],
  "temperature": 0.7,
  "max_tokens": 300
}

{
  "properties": {
    "hs_timestamp": "{{now}}",
    "hs_note_body": "Daily waitlist outreach sent (Scenario AP).\nDate: {{formatDate(now; 'MMMM D, YYYY'; 'America/New_York')}}\nOpen slots offered: {{4.open_slots}}\nEmail sent to: {{6.properties.email}}\nAI message generated by claude-sonnet-4-6 via OpenRouter."
  },
  "associations": [
    {
      "to": { "id": "{{6.id}}" },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 202
        }
      ]
    }
  ]
}
